// Handshake de verificação do webhook da Meta (App Dashboard → WhatsApp →
// Configuração → Webhook). META_VERIFY_TOKEN é uma senha que você escolhe e
// configura em duas pontas: aqui (variável de ambiente do n8n) e no painel
// da Meta, no mesmo campo "Verify token".
const query = $input.item.json.query || {};
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];
const esperado = $env.META_VERIFY_TOKEN;

const valido = mode === 'subscribe' && !!esperado && token === esperado;
return { valido, challenge: valido ? challenge : '' };

// v4/Meta — resolvido pelo node "Postgres — Resolver tenant" a partir do
// phone_number_id. Mantém os nomes de campo remoteJid/instanceName do fluxo
// Evolution (agora: phone digits / phone_number_id) pra não precisar tocar
// nos nodes de lógica de menu/agendamento adiante.
const TENANT_ID = $input.item.json.tenant_id;

const body = $('Webhook — Meta (mensagens)').first().json.body;
const value = body.entry[0].changes[0].value;
const msg = value.messages[0];

const phone = msg.from; // já vem em formato internacional (ex: "5534998887777"), sem "+"
// Resposta de botão/lista interativa (type='interactive') manda o id
// escolhido em button_reply/list_reply — os ids são os mesmos "1"/"2"/"3"...
// que o texto puro sempre usou, então nenhum node de validação downstream
// precisa saber se a resposta veio de botão, lista ou texto digitado.
let message;
if (msg.type === 'interactive' && msg.interactive) {
  const reply = msg.interactive.button_reply || msg.interactive.list_reply;
  message = reply ? reply.id : '';
} else {
  message = ((msg.text && msg.text.body) || '').trim();
}
const pushName = (value.contacts && value.contacts[0] && value.contacts[0].profile && value.contacts[0].profile.name) || 'cliente';
const phoneNumberId = value.metadata.phone_number_id;

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const sessionKey = 'session_' + phone;
let session = staticData.sessions[sessionKey] || { step: 'menu', data: {} };

if (message === '0') {
  session = { step: 'menu', data: {} };
}

return {
  tenantId: TENANT_ID,
  phone,
  remoteJid: phone,
  message,
  pushName,
  instanceName: phoneNumberId,
  step: session.step,
  sessionData: session.data || {},
};

const item = $input.item.json;
const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + item.phone;

const responseText = 'Olá' + (item.pushName ? ', ' + item.pushName.split(' ')[0] : '') + '! 👋 Bem-vindo(a) a ' + $('Postgres — Resolver tenant').first().json.nome + '!\n\nComo posso te ajudar?';

staticData.sessions[sessionKey] = { step: 'menu_opcao', data: {} };

return {
  remoteJid: item.remoteJid,
  instanceName: item.instanceName,
  responseText,
  interativoTipo: 'botoes',
  interativoOpcoes: [
    { id: '1', title: 'Agendar' },
    { id: '2', title: 'Reagendar' },
    { id: '3', title: 'Cancelar' },
  ],
};

const item = $input.item.json;
const msg = item.message;
let acao = 'invalido';
if (msg === '1') acao = 'agendar';
else if (msg === '2') acao = 'reagendar';
else if (msg === '3') acao = 'cancelar';

return Object.assign({}, item, { acao });

const ctx = $('Menu opção — decidir').first().json;
const rows = $input.all().map(i => i.json);
// tenants.onboarding_horario_revisado só vira true quando o admin confirma
// o horário de funcionamento ao menos uma vez (Configuração no painel) — sem
// isso, o cálculo de horários disponíveis roda em cima de um valor padrão
// que pode não bater com o funcionamento real do salão.
const horarioRevisado = $('Postgres — Resolver tenant').first().json.onboarding_horario_revisado;

const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + ctx.phone;

let responseText;
let interativo = null;
if (rows.length === 0 || !horarioRevisado) {
  responseText = 'Estamos finalizando os últimos ajustes por aqui! 🛠️\n\nEm breve vamos te atender com muito carinho — tente novamente mais tarde.\n\n_Digite 0 para voltar ao menu._';
  staticData.sessions[sessionKey] = { step: 'menu', data: {} };
} else {
  responseText = 'Ótimo! Qual serviço você deseja? 💇';
  staticData.sessions[sessionKey] = { step: 'escolher_servico', data: { servicosDisponiveis: rows } };
  // WhatsApp: até 3 opções vira botão de resposta rápida, até 10 vira lista
  // interativa (limites da própria Meta) — acima disso cai pro texto
  // numerado de sempre, que não tem limite de itens.
  if (rows.length <= 3) {
    interativo = { tipo: 'botoes', opcoes: rows.map((s, idx) => ({ id: String(idx + 1), title: s.nome.length > 20 ? s.nome.slice(0, 19) + '…' : s.nome })) };
  } else if (rows.length <= 10) {
    interativo = { tipo: 'lista', tituloSecao: 'Serviços', botaoLista: 'Escolher serviço', opcoes: rows.map((s, idx) => ({ id: String(idx + 1), title: s.nome.length > 24 ? s.nome.slice(0, 23) + '…' : s.nome, description: s.duracao_minutos + 'min · R$ ' + Number(s.preco).toFixed(2) })) };
  } else {
    const linhas = rows.map((s, idx) => (idx + 1) + '️⃣ ' + s.nome + ' — ' + s.duracao_minutos + 'min — R$ ' + Number(s.preco).toFixed(2));
    responseText += '\n\n' + linhas.join('\n');
  }
}

return Object.assign(
  { remoteJid: ctx.remoteJid, instanceName: ctx.instanceName, responseText },
  interativo ? { interativoTipo: interativo.tipo, interativoOpcoes: interativo.opcoes, interativoTituloSecao: interativo.tituloSecao, interativoBotaoLista: interativo.botaoLista } : {}
);

// Roteia agendar/reagendar/cancelar/inválido — agora sempre consultando o
// atendimento atual do cliente antes de decidir o que responder (US
// "confirmar atendimento antes de reagendar/cancelar/agendar outro").
const ctx = $('Menu opção — decidir').first().json;
const atendimentoAtual = ($input.all().map((i) => i.json))[0] || null;

const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + ctx.phone;

function formatarAtendimento(a) {
  const d = new Date(a.data_hora);
  const texto = d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
  return (a.servico_nome || 'Atendimento') + ' em ' + texto;
}

const BOTOES_MENU = [{ id: '1', title: 'Agendar' }, { id: '2', title: 'Reagendar' }, { id: '3', title: 'Cancelar' }];
const BOTOES_SIM_NAO = [{ id: '1', title: 'Sim' }, { id: '2', title: 'Não' }];

let responseText = '';
let nextStep;
let nextData = {};
let interativo = null;
let listarServicos = false;

if (ctx.acao === 'agendar') {
  if (atendimentoAtual) {
    responseText = 'Você já tem um atendimento marcado:\n\n' + formatarAtendimento(atendimentoAtual) + '\n\nQuer marcar OUTRO atendimento, além desse?';
    nextStep = 'confirmar_atendimento_extra';
    interativo = { tipo: 'botoes', opcoes: BOTOES_SIM_NAO };
  } else {
    listarServicos = true;
  }
} else if (ctx.acao === 'reagendar') {
  if (!atendimentoAtual) {
    responseText = 'Não encontrei nenhum atendimento seu pra reagendar. 🤔\n\n_Digite 0 para voltar ao menu._';
    nextStep = 'menu';
  } else {
    responseText = 'Você quer reagendar este atendimento?\n\n' + formatarAtendimento(atendimentoAtual);
    nextStep = 'confirmar_reagendamento';
    nextData = { atendimentoId: atendimentoAtual.id, profissionalId: atendimentoAtual.profissional_id, profissionalNome: atendimentoAtual.profissional_nome, servicoId: atendimentoAtual.servico_id, servicoNome: atendimentoAtual.servico_nome, duracaoMinutos: atendimentoAtual.duracao_minutos };
    interativo = { tipo: 'botoes', opcoes: BOTOES_SIM_NAO };
  }
} else if (ctx.acao === 'cancelar') {
  if (!atendimentoAtual) {
    responseText = 'Não encontrei nenhum atendimento seu pra cancelar. 🤔\n\n_Digite 0 para voltar ao menu._';
    nextStep = 'menu';
  } else {
    responseText = 'Você quer cancelar este atendimento?\n\n' + formatarAtendimento(atendimentoAtual);
    nextStep = 'confirmar_cancelamento';
    nextData = { atendimentoId: atendimentoAtual.id };
    interativo = { tipo: 'botoes', opcoes: BOTOES_SIM_NAO };
  }
} else {
  // Depois de 3 tentativas inválidas seguidas na mesma etapa, reinicia o
  // fluxo do zero em vez de repetir a mesma pergunta pra sempre.
  const tentativas = ((ctx.sessionData && ctx.sessionData.tentativasInvalidas) || 0) + 1;
  if (tentativas >= 3) {
    responseText = 'Não consegui entender depois de algumas tentativas. 🙏 Vamos recomeçar!\n\nOlá' + (ctx.pushName ? ', ' + ctx.pushName.split(' ')[0] : '') + '! 👋 Bem-vindo(a) a ' + $('Postgres — Resolver tenant').first().json.nome + '!\n\nComo posso te ajudar?';
    nextStep = 'menu_opcao';
    nextData = {};
  } else {
    responseText = 'Opção inválida. Por favor, escolha:';
    nextStep = 'menu_opcao';
    nextData = { tentativasInvalidas: tentativas };
  }
  interativo = { tipo: 'botoes', opcoes: BOTOES_MENU };
}

if (!listarServicos) {
  staticData.sessions[sessionKey] = { step: nextStep, data: nextData };
}

return Object.assign(
  { remoteJid: ctx.remoteJid, instanceName: ctx.instanceName, responseText, listarServicos, tenantId: ctx.tenantId },
  interativo ? { interativoTipo: interativo.tipo, interativoOpcoes: interativo.opcoes } : {}
);

const item = $input.item.json;
const servicos = (item.sessionData && item.sessionData.servicosDisponiveis) || [];
const idx = parseInt(item.message, 10) - 1;
const valido = Number.isInteger(idx) && idx >= 0 && idx < servicos.length;

return Object.assign({}, item, { valido, servicoEscolhido: valido ? servicos[idx] : null });

const ctx = $('Validar serviço escolhido').first().json;
const rows = $input.all().map(i => i.json);

const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + ctx.phone;

let responseText;
let interativo = null;
if (rows.length === 0) {
  responseText = 'No momento não temos profissionais disponíveis para esse serviço. 😔\n\n_Digite 0 para voltar ao menu._';
  staticData.sessions[sessionKey] = { step: 'menu', data: {} };
} else if (rows.length === 1) {
  responseText = 'Qual data você prefere? 📅\n\nResponda no formato DD/MM\nEx: 25/06';
  staticData.sessions[sessionKey] = { step: 'escolher_data', data: { servico: ctx.servicoEscolhido, profissional: rows[0] } };
} else {
  responseText = 'Com quem você prefere? 💜';
  staticData.sessions[sessionKey] = { step: 'escolher_profissional', data: { servico: ctx.servicoEscolhido, profissionaisDisponiveis: rows } };
  if (rows.length <= 3) {
    interativo = { tipo: 'botoes', opcoes: rows.map((p, idx) => ({ id: String(idx + 1), title: p.nome.length > 20 ? p.nome.slice(0, 19) + '…' : p.nome })) };
  } else if (rows.length <= 10) {
    interativo = { tipo: 'lista', tituloSecao: 'Profissionais', botaoLista: 'Escolher profissional', opcoes: rows.map((p, idx) => ({ id: String(idx + 1), title: p.nome.length > 24 ? p.nome.slice(0, 23) + '…' : p.nome })) };
  } else {
    const linhas = rows.map((p, idx) => (idx + 1) + '️⃣ ' + p.nome);
    responseText += '\n\n' + linhas.join('\n');
  }
}

return Object.assign(
  { remoteJid: ctx.remoteJid, instanceName: ctx.instanceName, responseText },
  interativo ? { interativoTipo: interativo.tipo, interativoOpcoes: interativo.opcoes, interativoTituloSecao: interativo.tituloSecao, interativoBotaoLista: interativo.botaoLista } : {}
);

const item = $input.item.json;
const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + item.phone;
const servicos = (item.sessionData && item.sessionData.servicosDisponiveis) || [];

const tentativas = ((item.sessionData && item.sessionData.tentativasInvalidas) || 0) + 1;
let responseText;
let interativo = null;
if (tentativas >= 3) {
  responseText = 'Não consegui entender depois de algumas tentativas. 🙏 Vamos recomeçar!\n\nOlá' + (item.pushName ? ', ' + item.pushName.split(' ')[0] : '') + '! 👋 Bem-vindo(a) a ' + $('Postgres — Resolver tenant').first().json.nome + '!\n\nComo posso te ajudar?';
  staticData.sessions[sessionKey] = { step: 'menu_opcao', data: {} };
  interativo = { tipo: 'botoes', opcoes: [{ id: '1', title: 'Agendar' }, { id: '2', title: 'Reagendar' }, { id: '3', title: 'Cancelar' }] };
} else {
  responseText = 'Opção inválida. Escolha um serviço:';
  staticData.sessions[sessionKey] = { step: 'escolher_servico', data: Object.assign({}, item.sessionData, { tentativasInvalidas: tentativas }) };
  if (servicos.length <= 3) {
    interativo = { tipo: 'botoes', opcoes: servicos.map((s, idx) => ({ id: String(idx + 1), title: s.nome.length > 20 ? s.nome.slice(0, 19) + '…' : s.nome })) };
  } else if (servicos.length <= 10) {
    interativo = { tipo: 'lista', tituloSecao: 'Serviços', botaoLista: 'Escolher serviço', opcoes: servicos.map((s, idx) => ({ id: String(idx + 1), title: s.nome.length > 24 ? s.nome.slice(0, 23) + '…' : s.nome, description: s.duracao_minutos + 'min · R$ ' + Number(s.preco).toFixed(2) })) };
  } else {
    const linhas = servicos.map((s, idx) => (idx + 1) + '️⃣ ' + s.nome + ' — ' + s.duracao_minutos + 'min — R$ ' + Number(s.preco).toFixed(2));
    responseText += '\n\n' + linhas.join('\n');
  }
}

return Object.assign(
  { remoteJid: item.remoteJid, instanceName: item.instanceName, responseText },
  interativo ? { interativoTipo: interativo.tipo, interativoOpcoes: interativo.opcoes, interativoTituloSecao: interativo.tituloSecao, interativoBotaoLista: interativo.botaoLista } : {}
);

const item = $input.item.json;
const profissionais = (item.sessionData && item.sessionData.profissionaisDisponiveis) || [];
const idx = parseInt(item.message, 10) - 1;
const valido = Number.isInteger(idx) && idx >= 0 && idx < profissionais.length;

const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + item.phone;

let responseText;
let interativo = null;
if (valido) {
  const profissional = profissionais[idx];
  responseText = 'Qual data você prefere? 📅\n\nResponda no formato DD/MM\nEx: 25/06';
  staticData.sessions[sessionKey] = { step: 'escolher_data', data: { servico: item.sessionData.servico, profissional } };
} else {
  // Depois de 3 tentativas inválidas seguidas na mesma etapa, reinicia o
  // fluxo do zero em vez de repetir a mesma pergunta pra sempre.
  const tentativas = ((item.sessionData && item.sessionData.tentativasInvalidas) || 0) + 1;
  if (tentativas >= 3) {
    responseText = 'Não consegui entender depois de algumas tentativas. 🙏 Vamos recomeçar!\n\nOlá' + (item.pushName ? ', ' + item.pushName.split(' ')[0] : '') + '! 👋 Bem-vindo(a) a ' + $('Postgres — Resolver tenant').first().json.nome + '!\n\nComo posso te ajudar?';
    staticData.sessions[sessionKey] = { step: 'menu_opcao', data: {} };
    interativo = { tipo: 'botoes', opcoes: [{ id: '1', title: 'Agendar' }, { id: '2', title: 'Reagendar' }, { id: '3', title: 'Cancelar' }] };
  } else {
    responseText = 'Opção inválida. Escolha um profissional:';
    staticData.sessions[sessionKey] = { step: 'escolher_profissional', data: Object.assign({}, item.sessionData, { tentativasInvalidas: tentativas }) };
    if (profissionais.length <= 3) {
      interativo = { tipo: 'botoes', opcoes: profissionais.map((p, i) => ({ id: String(i + 1), title: p.nome.length > 20 ? p.nome.slice(0, 19) + '…' : p.nome })) };
    } else if (profissionais.length <= 10) {
      interativo = { tipo: 'lista', tituloSecao: 'Profissionais', botaoLista: 'Escolher profissional', opcoes: profissionais.map((p, i) => ({ id: String(i + 1), title: p.nome.length > 24 ? p.nome.slice(0, 23) + '…' : p.nome })) };
    } else {
      const linhas = profissionais.map((p, i) => (i + 1) + '️⃣ ' + p.nome);
      responseText += '\n\n' + linhas.join('\n');
    }
  }
}

return Object.assign(
  { remoteJid: item.remoteJid, instanceName: item.instanceName, responseText },
  interativo ? { interativoTipo: interativo.tipo, interativoOpcoes: interativo.opcoes, interativoTituloSecao: interativo.tituloSecao, interativoBotaoLista: interativo.botaoLista } : {}
);

const item = $input.item.json;
const dateRegex = /^(0?[1-9]|[12][0-9]|3[01])\/(0?[1-9]|1[0-2])$/;
const msg = item.message;
let valido = false;
let isoDate = null;
let displayDate = msg;

if (dateRegex.test(msg)) {
  const partes = msg.split('/').map(Number);
  const dia = partes[0];
  const mes = partes[1];
  const hoje = new Date();
  let ano = hoje.getFullYear();
  let candidata = new Date(ano, mes - 1, dia);
  const hojeSemHora = new Date(hoje.getFullYear(), hoje.getMonth(), hoje.getDate());
  if (candidata < hojeSemHora) {
    ano += 1;
    candidata = new Date(ano, mes - 1, dia);
  }
  if (candidata.getMonth() === mes - 1 && candidata.getDate() === dia) {
    valido = true;
    isoDate = ano + '-' + String(mes).padStart(2, '0') + '-' + String(dia).padStart(2, '0');
    displayDate = String(dia).padStart(2, '0') + '/' + String(mes).padStart(2, '0');
  }
}

return Object.assign({}, item, { valido, isoDate, displayDate });

const ctx = $('Validar data').first().json;
const ocupados = $input.all().map(i => i.json);

const duracaoServico = ctx.sessionData.servico.duracao_minutos;

// US12 — horário de funcionamento configurável por tenant (antes era uma
// lista fixa 09h-17h hardcoded). Gera slots de hora em hora entre abertura e
// fechamento, pulando o intervalo de almoço 12h-14h (mantido fixo — o modelo
// de configuração hoje só tem abertura/fechamento, sem campo de almoço).
const horarioTenant = $('Postgres — Horário do tenant').first().json;
function paraHHMM(pgTime) {
  return pgTime.slice(0, 5);
}
const aberturaHHMM = paraHHMM(horarioTenant.horario_abertura);
const fechamentoHHMM = paraHHMM(horarioTenant.horario_fechamento);
const ALMOCO_INICIO = '12:00';
const ALMOCO_FIM = '14:00';

function paraMinutosLocal(hhmm) {
  const partes = hhmm.split(':').map(Number);
  return partes[0] * 60 + partes[1];
}

const aberturaMin = paraMinutosLocal(aberturaHHMM);
const fechamentoMin = paraMinutosLocal(fechamentoHHMM);
const almocoInicioMin = paraMinutosLocal(ALMOCO_INICIO);
const almocoFimMin = paraMinutosLocal(ALMOCO_FIM);

const HORARIOS_BASE = [];
for (let m = aberturaMin; m < fechamentoMin; m += 60) {
  if (m >= almocoInicioMin && m < almocoFimMin) continue;
  const h = String(Math.floor(m / 60)).padStart(2, '0');
  const min = String(m % 60).padStart(2, '0');
  HORARIOS_BASE.push(h + ':' + min);
}

function paraMinutos(hhmm) {
  const partes = hhmm.split(':').map(Number);
  return partes[0] * 60 + partes[1];
}

const OFFSET_SP_MINUTOS = 180; // America/Sao_Paulo = UTC-3 (sem horário de verão desde 2019)
const intervalosOcupados = ocupados.map(o => {
  const inicio = new Date(o.data_hora);
  const inicioMinUtc = inicio.getUTCHours() * 60 + inicio.getUTCMinutes();
  const inicioMin = inicioMinUtc - OFFSET_SP_MINUTOS;
  return { inicio: inicioMin, fim: inicioMin + o.duracao_minutos };
});

const disponiveis = HORARIOS_BASE.filter(h => {
  const inicio = paraMinutos(h);
  const fim = inicio + duracaoServico;
  if (fim > fechamentoMin) return false;
  return !intervalosOcupados.some(o => inicio < o.fim && fim > o.inicio);
});

const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + ctx.phone;

let responseText;
if (disponiveis.length === 0) {
  responseText = 'Não há horários disponíveis em ' + ctx.displayDate + ' para ' + ctx.sessionData.profissional.nome + '. 😔\n\nTente outra data (DD/MM) ou digite 0 para voltar ao menu.';
  staticData.sessions[sessionKey] = { step: 'escolher_data', data: ctx.sessionData };
} else {
  responseText = 'Horários disponíveis em ' + ctx.displayDate + ': ⏰\n\n' + disponiveis.join(' • ');
  staticData.sessions[sessionKey] = { step: 'escolher_horario', data: Object.assign({}, ctx.sessionData, { data: ctx.isoDate, dataDisplay: ctx.displayDate, horariosDisponiveis: disponiveis }) };
}

return { remoteJid: ctx.remoteJid, instanceName: ctx.instanceName, responseText };

const item = $input.item.json;
const staticData = $getWorkflowStaticData('global');
const sessionKey = 'session_' + item.phone;

// Depois de 3 tentativas inválidas seguidas na mesma etapa, reinicia o
// fluxo do zero em vez de repetir a mesma pergunta pra sempre.
const tentativas = ((item.sessionData && item.sessionData.tentativasInvalidas) || 0) + 1;
let responseText;
if (tentativas >= 3) {
  responseText = 'Não consegui entender depois de algumas tentativas. 🙏 Vamos recomeçar!\n\nOlá' + (item.pushName ? ', ' + item.pushName.split(' ')[0] : '') + '! 👋 Bem-vindo(a) a ' + $('Postgres — Resolver tenant').first().json.nome + '!\n\nComo posso te ajudar?\n\n1️⃣ Agendar\n2️⃣ Reagendar\n3️⃣ Cancelar agendamento';
  staticData.sessions[sessionKey] = { step: 'menu_opcao', data: {} };
} else {
  responseText = 'Data inválida. Por favor, use o formato DD/MM.\nEx: 25/06';
  staticData.sessions[sessionKey] = { step: 'escolher_data', data: Object.assign({}, item.sessionData, { tentativasInvalidas: tentativas }) };
}

return { remoteJid: item.remoteJid, instanceName: item.instanceName, responseText };

const item = $input.item.json;
const horarios = (item.sessionData && item.sessionData.horariosDisponiveis) || [];

function normalizar(txt) {
  let t = txt.trim().toLowerCase().replace('h', '');
  if (/^\d{1,2}$/.test(t)) return t.padStart(2, '0') + ':00';
  if (/^\d{1,2}:\d{2}$/.test(t)) {
    const partes = t.split(':');
    return partes[0].padStart(2, '0') + ':' + partes[1];
  }
  return null;
}

